import{_ as e,o as i,c as l,an as a}from"./chunks/framework.DYPaCD9m.js";const x=JSON.parse('{"title":"Units, conversion factors and constants","description":"","frontmatter":{},"headers":[],"relativePath":"manual/units_constants.md","filePath":"manual/units_constants.md","lastUpdated":null}'),r={name:"manual/units_constants.md"};function d(n,t,g,s,h,o){return i(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="Units,-conversion-factors-and-constants" tabindex="-1">Units, conversion factors and constants <a class="header-anchor" href="#Units,-conversion-factors-and-constants" aria-label="Permalink to &quot;Units, conversion factors and constants {#Units,-conversion-factors-and-constants}&quot;">​</a></h1><p>All information in this manual is expressed in terms of the International System of Units (SI), which is based, in part, on the metre, kilogram, second and kelvin. Basic units, derived units, prefixes, and some useful physical constants and conversion factors are listed below.</p><h2 id="Table-1.-Basic-units" tabindex="-1">Table 1. Basic units <a class="header-anchor" href="#Table-1.-Basic-units" aria-label="Permalink to &quot;Table 1. Basic units {#Table-1.-Basic-units}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;"><em>Physical Quantity</em></th><th style="text-align:right;"><em>Quantity Symbol</em></th><th style="text-align:right;"><em>Unit</em></th><th style="text-align:right;"><em>Unit Symbol</em></th></tr></thead><tbody><tr><td style="text-align:right;">length</td><td style="text-align:right;"><em>l</em></td><td style="text-align:right;">metre</td><td style="text-align:right;">m</td></tr><tr><td style="text-align:right;">mass</td><td style="text-align:right;"><em>m</em></td><td style="text-align:right;">kilogram</td><td style="text-align:right;">kg</td></tr><tr><td style="text-align:right;">time</td><td style="text-align:right;"><em>t</em></td><td style="text-align:right;">second</td><td style="text-align:right;">s</td></tr><tr><td style="text-align:right;">thermodynamic temperature</td><td style="text-align:right;"><em>T</em></td><td style="text-align:right;">kelvin</td><td style="text-align:right;">K</td></tr></tbody></table><h2 id="Table-2.-Derived-units" tabindex="-1">Table 2. Derived units <a class="header-anchor" href="#Table-2.-Derived-units" aria-label="Permalink to &quot;Table 2. Derived units {#Table-2.-Derived-units}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;"><em>Physical Quantity</em></th><th style="text-align:right;"><em>Quantity Symbol</em></th><th style="text-align:right;"><em>Unit</em></th><th style="text-align:right;"><em>Unit Symbol</em></th><th style="text-align:right;"><em>Unit Definition</em></th></tr></thead><tbody><tr><td style="text-align:right;">force</td><td style="text-align:right;"><em>F</em></td><td style="text-align:right;">newton</td><td style="text-align:right;">N</td><td style="text-align:right;">J m⁻¹</td></tr><tr><td style="text-align:right;">energy</td><td style="text-align:right;"><em>E</em></td><td style="text-align:right;">joule</td><td style="text-align:right;">J</td><td style="text-align:right;">N m</td></tr><tr><td style="text-align:right;">pressure</td><td style="text-align:right;"><em>p</em></td><td style="text-align:right;">pascal</td><td style="text-align:right;">Pa</td><td style="text-align:right;">N m⁻², J m⁻³</td></tr><tr><td style="text-align:right;">power</td><td style="text-align:right;"><em>P</em></td><td style="text-align:right;">watt</td><td style="text-align:right;">W</td><td style="text-align:right;">J s⁻¹</td></tr><tr><td style="text-align:right;">volume</td><td style="text-align:right;"><em>t</em></td><td style="text-align:right;">cubic metre</td><td style="text-align:right;">m³</td><td style="text-align:right;">m³</td></tr><tr><td style="text-align:right;">Celsius temperature*</td><td style="text-align:right;">t</td><td style="text-align:right;">degree Celsius</td><td style="text-align:right;">°C</td><td style="text-align:right;">K</td></tr></tbody></table><h2 id="Table-3.-Prefixes" tabindex="-1">Table 3. Prefixes <a class="header-anchor" href="#Table-3.-Prefixes" aria-label="Permalink to &quot;Table 3. Prefixes {#Table-3.-Prefixes}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;"><em>Multiple</em></th><th style="text-align:right;"><em>Prefix</em></th><th style="text-align:right;"><em>Symbol</em></th><th style="text-align:right;"><em>Multiple</em></th><th style="text-align:right;"><em>Prefix</em></th><th style="text-align:right;"><em>Symbol</em></th></tr></thead><tbody><tr><td style="text-align:right;">10⁻¹</td><td style="text-align:right;">deci</td><td style="text-align:right;"><em>d</em></td><td style="text-align:right;">10¹</td><td style="text-align:right;">deca</td><td style="text-align:right;">da</td></tr><tr><td style="text-align:right;">10⁻²</td><td style="text-align:right;">centi</td><td style="text-align:right;"><em>c</em></td><td style="text-align:right;">10²</td><td style="text-align:right;">hecto</td><td style="text-align:right;">h</td></tr><tr><td style="text-align:right;">10⁻³</td><td style="text-align:right;">milli</td><td style="text-align:right;"><em>m</em></td><td style="text-align:right;">10³</td><td style="text-align:right;">kilo</td><td style="text-align:right;">k</td></tr><tr><td style="text-align:right;">10⁻⁶</td><td style="text-align:right;">micro</td><td style="text-align:right;">μ</td><td style="text-align:right;">10⁶</td><td style="text-align:right;">mega</td><td style="text-align:right;">M</td></tr><tr><td style="text-align:right;">10⁻⁹</td><td style="text-align:right;">nano</td><td style="text-align:right;"><em>n</em></td><td style="text-align:right;">10⁹</td><td style="text-align:right;">giga</td><td style="text-align:right;">G</td></tr><tr><td style="text-align:right;">10⁻¹²</td><td style="text-align:right;">pico</td><td style="text-align:right;"><em>p</em></td><td style="text-align:right;">10¹²</td><td style="text-align:right;">tera</td><td style="text-align:right;">T</td></tr></tbody></table><h2 id="Table-4.-Conversion-factors" tabindex="-1">Table 4. Conversion factors <a class="header-anchor" href="#Table-4.-Conversion-factors" aria-label="Permalink to &quot;Table 4. Conversion factors {#Table-4.-Conversion-factors}&quot;">​</a></h2><p><strong>Force</strong></p><ul><li><p>dyne = 10⁵ N*</p></li><li><p>kilogram force = 9.80665 N*</p></li><li><p>ounce force = 2.7801385 × 10⁻¹ N</p></li><li><p>pound force = 4.4482216152605 N*</p></li></ul><p><strong>Energy</strong></p><ul><li><p>British thermal unit (thermochemical) = 1.054350 × 10³ J</p></li><li><p>calorie (thermochemical) = 4.184 J</p></li><li><p>what hour = 3.60 × 10³ J*</p></li></ul><p><strong>Pressure</strong></p><ul><li><p>bar = 10⁵ Pa*</p></li><li><p>centimetre of water (4 °C) = 9.80638 × 10¹ Pa</p></li><li><p>millimetre of mercury (0 °C) = 1.333224 × 10² Pa</p></li><li><p>pound per square inch = 6.894757 × 10³ Pa</p></li><li><p>standard atmosphere = 1.01325 × 10⁵ Pa</p></li><li><p>torr = 1.333224 × 10² Pa</p></li></ul><p><strong>Power</strong></p><ul><li><p>British thermal unit (thermochemical) = 1.054350 × 10³ W</p></li><li><p>calorie (thermochemical) per second = 4.184 W*</p></li><li><p>calorie (thermochemical) per minute = 6.973333 × 10⁻² W</p></li><li><p>kilocalorie (thermochemical) per hour = 8.604207 × 10⁻¹ W</p></li></ul><p><strong>Volume</strong></p><ul><li><p>cubic foot = 2.8316592 m³*</p></li><li><p>gallon = 3.785411784 × 10⁻³ m³*</p></li><li><p>litre = 10⁻³ m³*</p></li><li><p>pint (U.S. liquid) = 4.73176473 × 10⁻⁴ m³*</p></li><li><p>quart (U.S. liquid) = 9.4635295 × 10⁻⁴ m³*</p></li></ul><p><strong>Length</strong></p><ul><li><p>foot = 3.048 × 10⁻¹ m*</p></li><li><p>inch = 2.54 × 10⁻² m*</p></li><li><p>mile (U.S. statute) = 1.609344 × 10³ m*</p></li><li><p>mile (U.S. nautical) = 1.852 × 10³ m*</p></li><li><p>yard = 9.144 × 10⁻¹ m*</p></li></ul><p><strong>Mass</strong></p><ul><li><p>ounce = 2.8349523125 × 10⁻² kg*</p></li><li><p>pound = 4.5359237 × 10⁻¹ kg*</p></li><li><p>ton (short, 2000 pound) = 9.0718474 × 10² kg*</p></li></ul><p>*exact, by definition</p><h2 id="Table-5.-Physical-constants" tabindex="-1">Table 5. Physical constants <a class="header-anchor" href="#Table-5.-Physical-constants" aria-label="Permalink to &quot;Table 5. Physical constants {#Table-5.-Physical-constants}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;"><em>Quantity</em></th><th style="text-align:right;"><em>Symbol</em></th><th style="text-align:right;"><em>Value</em></th><th style="text-align:right;"><em>Units</em></th></tr></thead><tbody><tr><td style="text-align:right;">Density of dry air at 25 °C and 101325 Pa</td><td style="text-align:right;">ρ</td><td style="text-align:right;">1.184</td><td style="text-align:right;">kg m⁻³</td></tr><tr><td style="text-align:right;">Diffusivity of water vapor in air at 25 °C and 101325 Pa</td><td style="text-align:right;"><em>D</em></td><td style="text-align:right;">2.614 × 10⁻⁵</td><td style="text-align:right;">m² s⁻¹</td></tr><tr><td style="text-align:right;">Dynamic viscosity of dry air at 25 °C and 101325 Pa</td><td style="text-align:right;">μ</td><td style="text-align:right;">1.806 × 10⁻⁵</td><td style="text-align:right;">kg m⁻¹ s⁻¹</td></tr><tr><td style="text-align:right;">Gas constant for ideal gas</td><td style="text-align:right;"><em>R</em></td><td style="text-align:right;">8.31434</td><td style="text-align:right;">J mol⁻¹ K⁻¹</td></tr><tr><td style="text-align:right;">Gas constant for water vapor</td><td style="text-align:right;">_R_ᵥ</td><td style="text-align:right;">4.6150 × 10²</td><td style="text-align:right;">Pa m³ kg⁻¹ K⁻¹</td></tr><tr><td style="text-align:right;">Gravitational constant</td><td style="text-align:right;"><em>G</em></td><td style="text-align:right;">6.6732 × 10⁻¹¹</td><td style="text-align:right;">N m² kg⁻²</td></tr><tr><td style="text-align:right;">Kinematic viscosity of dry air at 25 °C and 101325 Pa</td><td style="text-align:right;">ν</td><td style="text-align:right;">1.525 × 10⁻⁵</td><td style="text-align:right;">m² s⁻¹</td></tr><tr><td style="text-align:right;">Latent heat of vaporization of water at 25 °C</td><td style="text-align:right;"><em>L</em></td><td style="text-align:right;">2.442 × 10⁶</td><td style="text-align:right;">J kg⁻¹</td></tr><tr><td style="text-align:right;">Molecular weight of dry air</td><td style="text-align:right;">_M_ₐ</td><td style="text-align:right;">2.8966 × 10⁻²</td><td style="text-align:right;">kg mol⁻¹</td></tr><tr><td style="text-align:right;">Molecular weight of water</td><td style="text-align:right;">_M_ᵥ</td><td style="text-align:right;">1.8016 × 10⁻²</td><td style="text-align:right;">kg mol⁻¹</td></tr><tr><td style="text-align:right;">Specific heat of dry air</td><td style="text-align:right;">_c_ₚ</td><td style="text-align:right;">1.00484 × 10³</td><td style="text-align:right;">J kg⁻¹ K⁻¹</td></tr><tr><td style="text-align:right;">Standard pressure</td><td style="text-align:right;">_P_₀</td><td style="text-align:right;">1.01325 × 10⁵</td><td style="text-align:right;">Pa</td></tr><tr><td style="text-align:right;">Standard temperature</td><td style="text-align:right;">_T_₀</td><td style="text-align:right;">2.7315 × 10²</td><td style="text-align:right;">K</td></tr><tr><td style="text-align:right;">Stefan-Boltzmann constant</td><td style="text-align:right;">σ</td><td style="text-align:right;">5.67032 × 10⁻⁸</td><td style="text-align:right;">W m⁻² K⁻⁴</td></tr><tr><td style="text-align:right;">Thermal conductivity of dry air at 25 °C and 101325 Pa</td><td style="text-align:right;"><em>k</em></td><td style="text-align:right;">2.601 × 10⁻²</td><td style="text-align:right;">W m⁻¹ K⁻¹</td></tr></tbody></table>',26)])])}const m=e(r,[["render",d]]);export{x as __pageData,m as default};
